 /** Explain selected module effects and recovery without a generic security verdict. @return array<string,string> */
 public static function impacts(): array { return array(
 'xmlrpc' => __( 'External XML-RPC publishing and pingbacks stop. Blocking happens after WordPress starts. To restore access, turn this option off and save, or deactivate Site Essentials.', 'site-essentials' ),
 'feeds' => __( 'Feed readers and external feed consumers receive HTTP 404. No posts are deleted. To restore feeds, turn this option off and save, or deactivate Site Essentials.', 'site-essentials' ),
 'template_editor' => __( 'Template editing and direct Site Editor access are blocked; saved templates still render. To restore editing, turn this option off and save, or deactivate Site Essentials.', 'site-essentials' ),
 'jquery_migrate' => __( 'Older frontend scripts may rely on jQuery Migrate. Test public pages while signed out. Login, admin and signed-in builder sessions retain it. To restore it, turn this option off and save.', 'site-essentials' ),
 'file_editors' => __( 'Single-site file-editor permissions are denied without setting global constants. Existing restrictions remain effective. To restore the previous permission behavior, turn this option off and save, or deactivate Site Essentials.', 'site-essentials' ),
 'classic_editor_types' => __( 'Changing editors does not convert content. Editing complex blocks in the classic editor may alter their markup. Clear the selected types and save to return to the existing editor decision; stricter rules from other plugins remain effective.', 'site-essentials' ),
 'classic_widgets' => __( 'Existing block widgets remain stored and can still render. This changes their editing interface only. Turn this option off and save to return to the theme’s normal widget editor.', 'site-essentials' ),
 'auto_embeds' => __( 'This stops automatic URL conversion only in content and widgets without block markup. Any content containing blocks keeps the existing automatic embedding behavior to preserve authored embed blocks. Shortcodes can still contact providers; this is not an external-request blocker. Turn this option off and save to restore automatic URL embeddings.', 'site-essentials' ),
 'embed_provider' => __( 'Existing embeds of your posts, including within this site, can stop working after their caches expire. Own embed pages return HTTP 404; ordinary pages remain public. This does not prevent manual iframes or copying public content. Turn this option off and save to restore WordPress embed responses.', 'site-essentials' ),
 'comments_disabled' => __( 'This overrides the individual comment rules without deleting comments or changing stored discussion options. Core templates, comment blocks, feeds and management screens are suppressed. Internal editor notes and system data remain available through their normal authorization. Shared WordPress styles are retained; custom third-party comment output needs separate verification. Turn this option off and save to restore the individual rules.', 'site-essentials' ),
 'local_avatars' => __( 'Core avatar HTML and URLs use locally served images only, without a Gravatar fallback. Invalid or external image URLs fall back to the local placeholder. Subscriber uploads are limited to their authorized profile and do not grant general media permissions. Uploaded files remain normal public WordPress media. Custom avatar HTML and previously cached pages need separate verification. Turn this option off and save to return to previous avatar behavior; assignments remain stored.', 'site-essentials' ),
 ); }
 /** Read defaults without enabling any cleanup. @return array<string,mixed> */
